<form method="post" action="<?= $u('account/addresses') ?>"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><?php if ($edit): ?><input type="hidden" name="id" value="<?= $e($edit['id']) ?>"><input type="hidden" name="revision" value="<?= $e($edit['revision']) ?>"><?php endif; ?><div class="form-grid"><?php foreach (['label'=>'Address label','recipient'=>'Recipient','phone'=>'Phone','line1'=>'Address line 1','line2'=>'Address line 2 (optional)','city'=>'City','state'=>'State','postal_code'=>'PIN code'] as $field=>$label): ?><label><?= $e($label) ?><input name="<?= $e($field) ?>" value="<?= $e($edit[$field] ?? ($field === 'label' ? 'Home' : '')) ?>" <?= $field === 'line2' ? '' : 'required' ?> maxlength="<?= in_array($field,['city','state'],true) ? 100 : ($field === 'label' ? 40 : ($field === 'phone' ? 20 : ($field === 'postal_code' ? 16 : 190))) ?>"></label><?php endforeach; ?></div><label><input type="checkbox" name="is_default" value="1" <?= !empty($edit['is_default']) ? 'checked' : '' ?>> Use as default address</label><button>Save address</button></form>
